// Fixed addition in an 80-edge deletion; necessary four-neighbor covers on the augmented graph.
use std::io::{self,BufRead};
fn sevens(a:&[u32;27],mut p:u32,k:u32,set:u32,out:&mut Vec<u32>){if k==0{out.push(set);return}while p.count_ones()>=k{let x=p&p.wrapping_neg();p^=x;sevens(a,p&!a[x.trailing_zeros() as usize],k-1,set|x,out)}}
fn main(){let mut hist=[[0u64;27];27];let mut ds=[0u64;2];let mut sample=false;for l in io::stdin().lock().lines(){let l=l.unwrap();let(id,g)=l.split_once(' ').unwrap();let b=g.as_bytes();let mut a=[0u32;27];let mut ec=0;let mut t=0;for j in 0..27{for i in 0..j{if (b[1+t/6]-63)>>(5-t%6)&1==1{ec+=1;a[i]|=1<<j;a[j]|=1<<i}t+=1}}if !(0..27).any(|i|ec-a[i].count_ones()==80){continue}let full=(1<<27)-1;let mut ss=vec![];sevens(&a,full,7,0,&mut ss);
for z in 0..27{if ec-a[z].count_ones()!=80{continue}ds[0]+=1;let p=full^(1<<z);let mut fs=[[0u32;27];27];let mut orig=0;for v in 0..27{if v==z{continue}let bv=1<<v;let ns=a[v]&p;let q:Vec<u32>=ss.iter().copied().filter(|s|s&((1<<z)|bv)==0).collect();let mut k=ns;let mut viable=false;while k!=0{let n=k.count_ones();if n==3||n==4{let mut common=p&!bv;let mut missed=false;for &s in &q{if s&k==0{missed=true;common&=s;if common==0{break}}}if n==3{let mut xs=common&!ns;while xs!=0{let j=xs.trailing_zeros() as usize;xs&=xs-1;fs[v.min(j)][v.max(j)]|=bv}}else{if !missed{viable=true}let mut xs=common;while xs!=0{let j=xs.trailing_zeros() as usize;xs&=xs-1;let mut ys=xs&!a[j];while ys!=0{let h=ys.trailing_zeros() as usize;ys&=ys-1;fs[j][h]|=bv}}}}k=(k-1)&ns;}if viable{orig+=1}}
let mut good=false;for j in 0..27{for i in 0..j{if i==z||j==z||a[i]>>j&1!=0{continue}let n=fs[i][j].count_ones();hist[orig][n as usize]+=1;if n>=6{good=true;if !sample&&orig<6{eprintln!("{} {} {} {} {} {} {:?}",id,z,orig,i,j,n,(0..27).filter(|v|fs[i][j]>>v&1!=0).collect::<Vec<_>>());sample=true}}}}if good{ds[1]+=1}}}println!("{} {}",ds[0],ds[1]);for i in 0..27{for j in 0..27{if hist[i][j]>0{println!("{} {} {}",i,j,hist[i][j])}}}}
